```yaml
name: PR Commit Security Scan

on:
  pull_request:
    types: [opened, synchronize, reopened]

jobs:
  brin-scan:
    runs-on: ubuntu-latest
    steps:
      - name: Checkout repository
        uses: actions/checkout@v4
        with:
          fetch-depth: 0

      - name: Set up Node.js
        uses: actions/setup-node@v4
        with:
          node-version: '20'

      - name: Install Brin CLI
        run: npm install -g @brin/cli

      - name: Get PR commits
        id: get_commits
        uses: actions/github-script@v6
        with:
          script: |
            const { data: commits } = await github.rest.pulls.listCommits({
              owner: context.repo.owner,
              repo: context.repo.repo,
              pull_number: context.payload.pull_request.number,
            });
            return commits.map(c => c.sha);
        outputs:
          commits: ${{ steps.get_commits.outputs.result }}

      - name: Scan commits with Brin
        id: scan
        env:
          BRIN_API_KEY: ${{ secrets.BRIN_API_KEY }}
        run: |
          echo "Scanning commits..."
          mkdir -p results
          echo "[]" > results/all.json
          for sha in $(echo "${{ steps.get_commits.outputs.commits }}" | jq -r '.[]'); do
            echo "Scanning $sha"
            brin scan --commit "$sha" --output json > "results/${sha}.json"
            cat "results/${sha}.json" >> results/all.json
          done

      - name: Aggregate results
        id: aggregate
        run: |
          blocking=0
          review=0
          inconclusive=0
          dangerous=0
          low_score=0
          comment_body="## Brin Security Scan\n\n"
          comment_body+="| Commit | Status | Score |\n"
          comment_body+="|--------|--------|-------|\n"
          for file in results/*.json; do
            sha=$(basename "$file" .json)
            status=$(jq -r '.status // "unknown"' "$file")
            score=$(jq -r '.score // 0' "$file")
            comment_body+="$sha | $status | $score |\n"
            case "$status" in
              "blocking"|"dangerous") blocking=$((blocking+1)); dangerous=$((dangerous+1));;
              "review") review=$((review+1));;
              "inconclusive") inconclusive=$((inconclusive+1));;
            esac
            if (( $(echo "$score < 30" | bc -l) )); then
              low_score=$((low_score+1))
            fi
          done
          echo "blocking=$blocking" >> $GITHUB_OUTPUT
          echo "review=$review" >> $GITHUB_OUTPUT
          echo "inconclusive=$inconclusive" >> $GITHUB_OUTPUT
          echo "dangerous=$dangerous" >> $GITHUB_OUTPUT
          echo "low_score=$low_score" >> $GITHUB_OUTPUT
          echo "comment_body<<EOF" >> $GITHUB_OUTPUT
          echo "$comment_body" >> $GITHUB_OUTPUT
          echo "EOF" >> $GITHUB_OUTPUT
        shell: bash

      - name: Manage PR comment
        uses: actions/github-script@v6
        env:
          COMMENT_BODY: ${{ steps.aggregate.outputs.comment_body }}
          DANGEROUS: ${{ steps.aggregate.outputs.dangerous }}
          LOW_SCORE: ${{ steps.aggregate.outputs.low_score }}
        with:
          script: |
            const marker = "## Brin Security Scan";
            const { data: comments } = await github.rest.issues.listComments({
              owner: context.repo.owner,
              repo: context.repo.repo,
              issue_number: context.payload.pull_request.number,
            });
            let commentId = null;
            for (const c of comments) {
              if (c.body.includes(marker)) {
                commentId = c.id;
                break;
              }
            }
            const body = process.env.COMMENT_BODY;
            const dangerous = parseInt(process.env.DANGEROUS, 10);
            const lowScore = parseInt(process.env.LOW_SCORE, 10);
            if (dangerous > 0 || lowScore > 0) {
              if (commentId) {
                await github.rest.issues.updateComment({
                  owner: context.repo.owner,
                  repo: context.repo.repo,
                  comment_id: commentId,
                  body,
                });
              } else {
                await github.rest.issues.createComment({
                  owner: context.repo.owner,
                  repo: context.repo.repo,
                  issue_number: context.payload.pull_request.number,
                  body,
                });
              }
            } else {
              if (commentId) {
                await github.rest.issues.deleteComment({
                  owner: context.repo.owner,
                  repo: context.repo.repo,
                  comment_id: commentId,
                });
              }
            }

      - name: Fail if dangerous or low score
        if: ${{ steps.aggregate.outputs.dangerous != '0' || steps.aggregate.outputs.low_score != '0' }}
        run: exit 1
